import math
        import random
        import time

        LANGUAGE_WRAPPER = "In a math contest with {N} problems, one's score, `s`, is computed by the formula `s = {S0} + {Pc}*c - {Pw}*w`, where `c` is the number of correct answers and `w` is the number of wrong answers. Mary told John her score, which was over {L}. From this, John was able to determine the number of problems Mary solved correctly. If Mary's score had been any lower, but still over {L}, John could not have determined this. What was Mary's score?"

        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        import math

def generator(rng):
    while True:
        pw = rng.randint(2, 4)
        pc = rng.randint(pw + 1, pw + 7)
        if math.gcd(pc, pw) != 1:
            continue

        n = rng.randint(35, 55)
        s0 = pw * n

        A = pc + pw
        B = pw

        try:
            pc_inv = pow(pc, -1, B)
        except ValueError:
            continue

        memo = {}
        def count_solutions(s):
            if s in memo: return memo[s]
            if s < 0: 
                memo[s] = 0
                return 0

            low_c_num = s - B * n
            low_c = (low_c_num + pc - 1) // pc if pc > 0 else (low_c_num) // pc
            high_c = s // A

            if low_c > high_c:
                memo[s] = 0
                return 0

            target_rem = (s * pc_inv) % B

            rem = low_c % B
            first_c = low_c + (target_rem - rem + B) % B

            if first_c > high_c:
                memo[s] = 0
                return 0

            count = 1 + (high_c - first_c) // B
            memo[s] = count
            return count

        s_search_start = A * (n - pc) - 4 * A
        if s_search_start < 0: s_search_start = 0

        s1 = -1
        for s in range(s_search_start, A * n + 1):
            if count_solutions(s) == 1 and count_solutions(s-1) != 1:
                s1 = s
                break
        if s1 == -1: continue

        s2 = -1
        for s in range(s1 + 1, A * n + 1):
            if count_solutions(s) == 1:
                s2 = s
                break
        if s2 == -1: continue

        gap_is_good = False
        if s2 > s1 + 1:
            all_non_unique = True
            for s in range(s1 + 1, s2):
                if count_solutions(s) == 1:
                    all_non_unique = False
                    break
            if all_non_unique:
                gap_is_good = True

        if gap_is_good and s2 - s1 > 2:
            return {
                'N': n,
                'S0': s0,
                'Pc': pc,
                'Pw': pw,
                'L': s1,
                'answer': s2
            }

        import math

def verifier(assign):
    n = assign['N']
    s0 = assign['S0']
    pc = assign['Pc']
    pw = assign['Pw']
    L = assign['L']
    answer = assign['answer']

    if not (2 <= pw <= 4 and pw + 1 <= pc <= pw + 7 and 35 <= n <= 55):
        return False, None # Parameter range check
    if math.gcd(pc, pw) != 1:
        return False, None # Pc and Pw must be coprime
    if s0 != pw * n:
        return False, None # S0 must follow generator logic

    A = pc + pw
    B = pw
    pc_inv = pow(pc, -1, B)

    memo = {}
    def count_solutions(s):
        if s in memo: return memo[s]
        if s < 0: return 0

        low_c_num = s - B * n
        low_c = (low_c_num + pc - 1) // pc if pc > 0 else (low_c_num) // pc
        high_c = s // A

        if low_c > high_c:
            memo[s] = 0
            return 0

        target_rem = (s * pc_inv) % B
        rem = low_c % B
        first_c = low_c + (target_rem - rem + B) % B

        if first_c > high_c:
            memo[s] = 0
            return 0

        count = 1 + (high_c - first_c) // B
        memo[s] = count
        return count

    # 1. Mary's score (the answer) must have a unique solution for c.
    if count_solutions(answer) != 1:
        return False, None # Answer is not a unique-solution score

    # 2. The lower bound L must be strictly less than the answer.
    if not (L < answer):
        return False, None

    # 3. The problem states the score is 'over L'. The smallest such score with a unique solution is the answer.
    #    This implies any integer score s' with L < s' < answer must NOT have a unique solution.
    for s in range(L + 1, answer):
        if count_solutions(s) == 1:
            return False, None # Found a unique score in the gap (L, answer), violating problem condition

    # 4. To make the problem non-trivial, L itself should be a score with a unique solution,
    #    and the score just below it should not be.
    if count_solutions(L) != 1:
        return False, None # L is not a unique-solution score
    if count_solutions(L - 1) == 1:
        return False, None # The problem could have been posed with a lower L

    return True, answer


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

